import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CQdiwDJy.js";const p=JSON.parse('{"title":"Multi-round agent (tau goal)","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/goal.md","filePath":"en/guide/goal.md","lastUpdated":1788601681000}'),o={name:"en/guide/goal.md"};function r(s,e,l,d,h,u){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="multi-round-agent-tau-goal" tabindex="-1">Multi-round agent (tau goal) <a class="header-anchor" href="#multi-round-agent-tau-goal" aria-label="Permalink to &quot;Multi-round agent (tau goal)&quot;">​</a></h1><p><code>tau goal</code> turns Tau from a single-round diagnostician into a task agent: one intent can span up to five reviewed rounds — plan, run, reflect, repeat — with every round passing the same deterministic review, and the provider deciding after each round whether the goal is done.</p><h2 id="basic-usage" tabindex="-1">Basic usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;collect every TODO comment into a checklist file&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;refactor this script&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rounds</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span></span></code></pre></div><p>The round cap defaults to 3, is tunable with <code>--rounds</code>, and hard-ceils at 5. Caps guard against runaway loops; every proposed next-round plan must pass the safety review before it can run.</p><h2 id="life-of-a-round" tabindex="-1">Life of a round <a class="header-anchor" href="#life-of-a-round" aria-label="Permalink to &quot;Life of a round&quot;">​</a></h2><ol><li><strong>round_plan</strong>: the provider produces a plan (or a reflection continues with one), graded by the deterministic <code>reviewPlan()</code>.</li><li><strong>approval</strong>: non-low-risk rounds pause for your explicit approval — agent mode is never a blanket pre-authorization.</li><li><strong>execute</strong>: through the only execution channel, <code>runPlan()</code>; shell steps are cancellable end-to-end (abort kills the whole process group).</li><li><strong>reflect</strong>: the provider receives the executed rounds (outputs truncated to 4k chars each) and answers &quot;done (with a final answer)&quot; or &quot;one more round (with a plan)&quot;. A reflected plan is ALWAYS re-graded — the AI never grades itself.</li></ol><p>Round history in the prompt is capped (last 3 verbatim, older rounds summarized in one line) so long goals cannot blow the context.</p><h2 id="streaming-thinking-v0-5-0" tabindex="-1">Streaming thinking (v0.5.0) <a class="header-anchor" href="#streaming-thinking-v0-5-0" aria-label="Permalink to &quot;Streaming thinking (v0.5.0)&quot;">​</a></h2><p>In the WebUI agent mode, each round&#39;s planning thinking streams live: planning thinking and reflection thinking are tagged to their own rounds&#39; collapsible panels. Library integrations can consume round-tagged thinking deltas through <code>runGoal</code>&#39;s <code>onPlanStream</code> observer.</p><h2 id="providers-without-reflection" tabindex="-1">Providers without reflection <a class="header-anchor" href="#providers-without-reflection" aria-label="Permalink to &quot;Providers without reflection&quot;">​</a></h2><p><code>reflect()</code> is an optional capability. mock, OpenAI-compatible, Anthropic and Gemini implement it; Ollama, DeepSeek and Zai do not yet — they degrade honestly to a single executed round with a note, never silently pretending to be done.</p>`,12)])])}const g=a(o,[["render",r]]);export{p as __pageData,g as default};
